[CmdletBinding()]
param(
    # The folder to write the site ready to be published to; its contents are replaced
    [Parameter(Mandatory)]
    [string] $OutputPath,

    # The site generated by build.ps1
    [string] $SitePath = (Join-Path $PSScriptRoot "_site")
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Write-Step {
    param([string] $Message)

    Write-Host "`n==> $Message" -ForegroundColor Cyan
}

function Get-ContentHash {
    param([string] $Path)

    return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.Substring(0, 12).ToLowerInvariant()
}

function Get-CurrentPages {
    param([string] $Path)

    # The v4 docs are a static copy of the old site, built with another template
    $v4Path = (Join-Path $Path "v4") + [IO.Path]::DirectorySeparatorChar
    return Get-ChildItem -LiteralPath $Path -Filter "*.html" -Recurse -File |
        Where-Object { -not $_.FullName.StartsWith($v4Path, [StringComparison]::OrdinalIgnoreCase) }
}

function Add-AssetVersions {
    param([string] $Path)

    # GitHub Pages caches every file for 10 minutes, so the static assets get a content hash to avoid stale styles and scripts
    $publicPath = Join-Path $Path "public"
    $utf8 = [Text.UTF8Encoding]::new($false)

    # A shared chunk imports main.js, so main.js has to be versioned first to make the change flow into the chunk hash
    $scriptPaths = @(Get-ChildItem -LiteralPath $publicPath -Filter "*.js" -File | Select-Object -ExpandProperty FullName)
    $mainScriptImport = 'import("./main.js")'
    $chunkPaths = @($scriptPaths | Where-Object { [IO.File]::ReadAllText($_).Contains($mainScriptImport) })
    if ($chunkPaths.Count -ne 1) {
        throw "Expected the main.js import in exactly one script in '$publicPath', but found $($chunkPaths.Count)."
    }

    $chunkPath = $chunkPaths[0]
    $mainScriptHash = Get-ContentHash (Join-Path $publicPath "main.js")
    $chunk = [IO.File]::ReadAllText($chunkPath).Replace($mainScriptImport, "import(`"./main.js?v=$mainScriptHash`")")
    [IO.File]::WriteAllText($chunkPath, $chunk, $utf8)
    Write-Host "Versioned 'main.js' as '$mainScriptHash'."

    # The chunk keeps its name when main.js changes, so it gets a version too. Every reference has to use it, otherwise the
    # browser would load the chunk twice as separate modules. docfx.min.js references it, so the change reaches its hash too
    $chunkName = Split-Path -Leaf $chunkPath
    $chunkHash = Get-ContentHash $chunkPath
    foreach ($scriptPath in $scriptPaths) {
        $script = [IO.File]::ReadAllText($scriptPath)
        $updatedScript = $script.Replace("`"./$chunkName`"", "`"./${chunkName}?v=$chunkHash`"")

        if ($updatedScript -ne $script) {
            [IO.File]::WriteAllText($scriptPath, $updatedScript, $utf8)
        }
    }

    Write-Host "Versioned '$chunkName' as '$chunkHash'."

    $assetHashes = @{}
    foreach ($assetName in @("docfx.min.css", "main.css", "docfx.min.js")) {
        $assetHashes[$assetName] = Get-ContentHash (Join-Path $publicPath $assetName)
        Write-Host "Versioned '$assetName' as '$($assetHashes[$assetName])'."
    }

    $assetReferenceRegex = [regex] '(?<=["/])public/(docfx\.min\.css|main\.css|docfx\.min\.js)(?=")'
    $updatedPagesCount = 0

    foreach ($page in Get-CurrentPages $Path) {
        $content = [IO.File]::ReadAllText($page.FullName)
        $updatedContent = $assetReferenceRegex.Replace(
            $content,
            { param($match) "$($match.Value)?v=$($assetHashes[$match.Groups[1].Value])" })

        if ($updatedContent -ne $content) {
            [IO.File]::WriteAllText($page.FullName, $updatedContent, $utf8)
            $updatedPagesCount++
        }
    }

    Write-Host "Added the asset versions to $updatedPagesCount pages."
}

function Update-Sitemap {
    param([string] $Path)

    $sitemapPath = Join-Path $Path "sitemap.xml"
    [xml] $sitemap = [IO.File]::ReadAllText($sitemapPath)
    $namespaces = [Xml.XmlNamespaceManager]::new($sitemap.NameTable)
    $namespaces.AddNamespace("s", "http://www.sitemaps.org/schemas/sitemap/0.9")

    # GitHub Pages serves 404.html for every missing path, so it must not be listed as a page
    $errorPageUrls = @($sitemap.SelectNodes("/s:urlset/s:url[substring(s:loc, string-length(s:loc) - 8) = '/404.html']", $namespaces))
    if ($errorPageUrls.Count -ne 1) {
        throw "Expected exactly one 404.html entry in '$sitemapPath', but found $($errorPageUrls.Count)."
    }

    $errorPageUrls[0].ParentNode.RemoveChild($errorPageUrls[0]) | Out-Null

    # The home page declares the site root as its canonical URL, so the sitemap has to list the same URL
    $homeLocations = @($sitemap.SelectNodes("/s:urlset/s:url/s:loc[text() = 'https://silverback-messaging.net/index.html']", $namespaces))
    if ($homeLocations.Count -ne 1) {
        throw "Expected exactly one home page entry in '$sitemapPath', but found $($homeLocations.Count)."
    }

    $homeLocations[0].InnerText = "https://silverback-messaging.net/"

    $settings = [Xml.XmlWriterSettings]::new()
    $settings.Encoding = [Text.UTF8Encoding]::new($false)
    $settings.Indent = $true
    $writer = [Xml.XmlWriter]::Create($sitemapPath, $settings)
    try {
        $sitemap.Save($writer)
    }
    finally {
        $writer.Dispose()
    }

    Write-Host "Removed the 404.html entry and set the home page entry to the site root."
}

Write-Step "Checking the generated site"
if (-not (Test-Path -LiteralPath $SitePath -PathType Container)) {
    throw "The generated site was not found at '$SitePath'. Run the documentation build first."
}

$SitePath = (Resolve-Path -LiteralPath $SitePath).Path
$siteItems = @(Get-ChildItem -LiteralPath $SitePath -Force)
if ($siteItems.Count -eq 0) {
    throw "The generated site at '$SitePath' is empty."
}

# docfx only warns about a missing include and leaves its raw markup in the page: the generated files exist only after build.ps1
$unresolvedIncludes = @(Get-CurrentPages $SitePath | Select-String -Pattern "[!include[" -SimpleMatch -List)
if ($unresolvedIncludes.Count -gt 0) {
    throw "The generated site contains unresolved includes (e.g. '$($unresolvedIncludes[0].Path)'). Build it with build.ps1."
}

Write-Step "Copying the generated site to '$OutputPath'"
if (Test-Path -LiteralPath $OutputPath) {
    Remove-Item -LiteralPath $OutputPath -Recurse -Force
}

New-Item -ItemType Directory -Path $OutputPath | Out-Null
$OutputPath = (Resolve-Path -LiteralPath $OutputPath).Path
$siteItems | Copy-Item -Destination $OutputPath -Recurse -Force

Write-Step "Adding the cache-busting asset versions"
Add-AssetVersions $OutputPath

Write-Step "Updating the sitemap"
Update-Sitemap $OutputPath
